-- SECURITY DEFINER; API roles that may call it: authenticated, service_role
CREATE OR REPLACE FUNCTION public.community_aircraft()
 RETURNS TABLE(aircraft text, flights bigint, creators bigint, faces jsonb)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with rows_ as (
    select btrim(f.aircraft) as aircraft, f.creator_id, p.name, p.photo_url
      from public.flights f
      join public.profiles p on p.id = f.creator_id
     where f.share_with_community
       and coalesce(btrim(f.aircraft), '') <> ''
       and f.flown_on <= current_date
       and p.is_test = false
       and p.status = 'active'
       and p.deletion_requested_at is null
  ),
  -- One row per creator per type, so the faces are people rather than flights.
  people as (
    select aircraft, creator_id, min(name) as name, min(photo_url) as photo_url,
           count(*) as their_flights
      from rows_
     group by aircraft, creator_id
  ),
  ranked as (
    select p.*, row_number() over (partition by p.aircraft order by p.their_flights desc, p.name) as rn
      from people p
  )
  select r.aircraft,
         (select count(*) from rows_ x where x.aircraft = r.aircraft)::bigint,
         count(*)::bigint,
         coalesce(jsonb_agg(
           jsonb_build_object('id', r.creator_id, 'name', r.name, 'photo_url', r.photo_url)
           order by r.rn
         ) filter (where r.rn <= 8), '[]'::jsonb)
    from ranked r
   group by r.aircraft
   order by count(*) desc, 2 desc
   limit 40;
$function$;
